Ext.define("bcp.view.PurchaseViewController", {
    extend: "Ext.app.ViewController",
    alias: "controller.purchases",

    showView: function (view) {
        var model = this.getViewModel(),
            layout = this.getView().getLayout(),
            refs = this.getReferences(),
            list = refs.list,
            reqList = refs.requestList,
            detail = refs[view]; //detail or editableDetail;

        if (view === "list") {
            reqList.setSelection(null);
            layout.setActiveItem(list);
        } else {
            layout.setActiveItem(detail);
        }

        //still need this for control the buttons in the toolbar
        model.set("viewState", view);
    },

    onBackToList: function (button, e, eOpts) {
        this.redirectTo("purchases", true);
    },

    onViewDetail: function (button, e, eOpts) {
        var refs = this.getReferences(),
            list = refs.requestList,
            req = list.selection;

        if (req) {
            var reqId = req.get("requestId");
            this.redirectTo("#purchases/" + reqId);
        }
        this.showView("detail");
    },

    edit: function (button, e, eOpts) {
        var refs = this.getReferences(),
            list = refs.requestList,
            rec = list.selection;

        if (rec) {
            refs.detail.destroy();
            bcp.util.CommonFunctions.setupEditableRequestDetailView(rec, this, this.getView());
        }

        this.showView("editableDetail");
    },

    onReload: function (button, e, eOpts) {
        var refs = this.getReferences(),
            reqList = refs.requestList;
        reqList.setSelection(null);
        Ext.getStore("ProcessedRequests").load();
    },

    onSelect: function (rowmodel, record, index, eOpts) {
        //reload history data with the selected record
        this.getReferences().historyview.getController().loadHistoryById(record.get("requestId"));
    },

    onFyChange: function (field, newValue, oldValue, eOpts) {
        if (oldValue != null) {
            localStorage.setItem("purchaseViewComboFyValue", newValue);
            var store = Ext.getStore("ProcessedRequests");
            store.proxy.url = "/empbc/v1/requests/processed/" + newValue;
            store.load();
        }
    },

    onMissingStmtDtChkboxChange: function (field, newValue, oldValue, eOpts) {
        if (oldValue != null) {
            var refs = this.getReferences(),
                reqList = refs.requestList;
            reqList.setSelection(null);
            //this value should be preserved if the view reload because users are likely
            //select a req from the filtered list, update the stmt date and go back to the
            //list to select another one to update
            localStorage.setItem("purchaseViewChkboxMissingStmtDtValue", newValue);
            var store = Ext.getStore("ProcessedRequests");
            store.getProxy().setExtraParam("showPurchaseWithMissingStmtDt", newValue);
            store.load();
        }
    },

    onUpdateOrderInfo: function (button, e, eOpts) {
        var model = this.getViewModel(),
            store = Ext.getStore("ProcessedRequests"),
            record = model.get("record"),
            reqId = record.get("requestId");

        var window = Ext.create("widget.orderwindow", {
            reference: "orderwindow"
        });
        var form = window.query("form")[0];
        form.loadRecord(record);

        //set event listeners
        window.on({
            cancelUpdateOrder: {
                fn: function (data) {
                    window.destroy();
                },
                scope: this,
                single: true
            }
        });
        window.on({
            applyUpdateOrder: {
                fn: function (data) {
                    Ext.Ajax.request({
                        url: bcp.config.Runtime.getServerBaseUrl() + "requests/" + reqId,
                        method: "PUT",
                        jsonData: Ext.encode(data),
                        scope: this,
                        success: function (response) {
                            store.reload();
                            window.destroy();
                        },
                        failure: function (response) {
                            store.reload();
                            window.destroy();
                        }
                    });
                },
                scope: this,
                single: true
            }
        });

        //add to the parent view
        this.view.add(window);

        // Show the window
        window.show();
    },

    onComplete: function (button, e, eOpts) {
        var model = this.getViewModel(),
            formWindow = Ext.create("widget.routewindow"),
            newRecord = {},
            record = this.getViewModel().get("record"),
            requestId = record.data.requestId,
            user = model.get("loggedInUser"),
            userId = user.peopleId;
        if (record.get("statusCode") === 9) {
            Ext.Msg.alert("warning", "This request is already delivered.");
            return;
        }

        Ext.MessageBox.show({
            title: "Purchase Delivered Confirmation",
            msg: "By marking this purchase request as [Delivered], you indicate that all items of the request were delivered, proceed?",
            width: 350,
            buttons: Ext.MessageBox.YESNO,
            data: requestId,
            fn: function (btn, data, self) {
                if (btn == "yes") {
                    newRecord = Ext.create("bcp.model.RequestRoute", {
                        requestId: record.get("requestId"),
                        statusId: 9
                    });
                    newRecord.set("typeId", 6);
                    newRecord.set("routeTo", userId);
                    newRecord.set("routeToName", user.lastName + ", " + user.firstName);

                    if (newRecord.data.routeTo !== 0) {
                        formWindow.lookupController().removeRouteToCombo();
                    }

                    //set record
                    formWindow.lookupController().getViewModel().set("record", newRecord);

                    //set original request record
                    formWindow.lookupController().getViewModel().set("req", record);

                    //load record
                    formWindow.lookupController().lookupReference("form").getForm().loadRecord(newRecord);
                    //set event listeners
                    formWindow.on({
                        cancelRoute: {
                            fn: function (win, data) {
                                formWindow.destroy();
                            },
                            scope: this,
                            single: true
                        }
                    });
                    formWindow.on({
                        routed: {
                            fn: function (win, data) {
                                formWindow.destroy();
                                var returnTo = this.getViewModel().get("returnToView");
                                if (returnTo) {
                                    this.redirectTo(returnTo, true);
                                } else {
                                    //send user to home view
                                    this.redirectTo("#dashboard");
                                }
                            },
                            scope: this,
                            single: true
                        }
                    });
                    //add window to view
                    this.view.add(formWindow);
                    //show window
                    formWindow.show();
                }
            },
            scope: this
        });
    },

    //mark the request "Received"
    onArchive: function (button, e, eOpts) {
        var formWindow = Ext.create("widget.routewindow"),
            newRecord = {},
            record = this.getViewModel().get("record"),
            requestId = record.data.requestId;

        Ext.MessageBox.show({
            title: "Purchase Received Confirmation",
            msg: "By marking this purchase request as [Received], you indicate that all items of the request were received by the requester and the request was fullfilled. The purchase request will be routed back to the requester now for record keeping, proceed?",
            width: 350,
            buttons: Ext.MessageBox.YESNO,
            data: requestId,
            fn: function (btn, data, self) {
                if (btn == "yes") {
                    newRecord = Ext.create("bcp.model.RequestRoute", {
                        requestId: record.get("requestId"),
                        statusId: 13
                    });
                    newRecord.set("typeId", 7);
                    newRecord.set("routeTo", record.get("requesterId"));
                    newRecord.set("routeToName", record.get("requesterName"));

                    if (newRecord.data.routeTo !== 0) {
                        formWindow.lookupController().removeRouteToCombo();
                    }

                    //set record
                    formWindow.lookupController().getViewModel().set("record", newRecord);

                    //set original request record
                    formWindow.lookupController().getViewModel().set("req", record);

                    //load record
                    formWindow.lookupController().lookupReference("form").getForm().loadRecord(newRecord);
                    //set event listeners
                    formWindow.on({
                        cancelRoute: {
                            fn: function (win, data) {
                                formWindow.destroy();
                            },
                            scope: this,
                            single: true
                        }
                    });
                    formWindow.on({
                        routed: {
                            fn: function (win, data) {
                                formWindow.destroy();
                                var returnTo = this.getViewModel().get("returnToView");
                                if (returnTo) {
                                    this.redirectTo(returnTo, true);
                                } else {
                                    //send user to home view
                                    this.redirectTo("#dashboard");
                                }
                            },
                            scope: this,
                            single: true
                        }
                    });
                    //add window to view
                    this.view.add(formWindow);
                    //show window
                    formWindow.show();
                }
            },
            scope: this
        });
    },
    onReassign: function (button, e, eOpts) {
        var model = this.getViewModel(),
            record = model.get("generalInfo"),
            status = record.get("statusCode"),
            store = {},
            formWindow = null,
            newRecord = Ext.create("bcp.model.RequestRoute", {
                requestId: record.get("requestId")
            });

        store = Ext.getStore("BankcardHolders");

        //set route type to "reroute"
        newRecord.set("typeId", 9);
        //reroute to the approver in the same step
        //e.g. if in review step, reroute to another reviewer to review
        newRecord.set("statusId", status);

        //create route window
        formWindow = Ext.create("widget.routewindow", {
            store: store
        });
        //set record
        formWindow.lookupController().getViewModel().set("record", newRecord);

        //set original request record
        formWindow.lookupController().getViewModel().set("req", record);

        //load record
        formWindow.lookupController().lookupReference("form").getForm().loadRecord(newRecord);
        //set event listeners
        formWindow.on({
            cancelRoute: {
                fn: function (win, data) {
                    formWindow.destroy();
                },
                scope: this,
                single: true
            }
        });
        formWindow.on({
            routed: {
                fn: function (win, data) {
                    formWindow.destroy();
                    //send user to home view
                    //this.redirectTo('#dashboard');
                },
                scope: this,
                single: true
            }
        });
        //add window to view
        this.view.add(formWindow);
        //show window
        formWindow.show();
    },
    //MB-438
    onCancelRequest: function (button, e, eOpts) {
        var model = this.getViewModel(),
            record = model.get("record"),
            currentStatus = record.get("statusCode"),
            newRoute = Ext.create("bcp.model.RequestRoute", {
                requestId: record.get("requestId"),
                statusId: 10
            }),
            me = this;

        if (currentStatus === 9) {
            Ext.Msg.alert("Warning", "Your request was already delivered and cannot be canceled.");
            return;
        } else if (currentStatus === 10) {
            Ext.Msg.alert("Warning", "Your request was already canceled.");
            return;
        }
        //no need for this since received is not in the purchase list
        //else if (currentStatus === 13) {
        //    Ext.Msg.alert("Warning", "You cannot cancel a received request.");
        //    return;
        //}

        newRoute.set("typeId", 8);
        //if someone prepared the request, route back to the creator
        if (record.get("creatorId") != record.get("requesterId")) {
            newRoute.set("routeTo", record.get("creatorId"));
            newRoute.set("routeToName", record.get("creatorName"));
        } else {
            //otherwise, route it to the requester
            newRoute.set("routeTo", record.get("requesterId"));
            newRoute.set("routeToName", record.get("requesterName"));
        }

        // Ask user to confirm this action
        Ext.Msg.confirm(
            "Cancel Request Confirmation",
            "Are you sure you want to cancel this request?",
            function (result) {
                // User confirmed yes
                if (result == "yes") {
                    Ext.Ajax.request({
                        url: bcp.config.Runtime.getServerBaseUrl() + "routes",
                        method: "POST",
                        jsonData: Ext.encode(newRoute.data),
                        scope: this,
                        success: function (response) {
                            bcp.util.CommonUtil.ajaxSuccessHandler(response, function (result) {
                                Ext.Msg.alert("Success", "Your request was canceled successfully.");
                                me.redirectTo("purchases", true);
                            });
                        },
                        failure: function (response) {
                            Ext.Msg.alert("Failed", response.result.statusText);
                        }
                    });
                }
            }
        );
    },

    onViewAdded: function (component, container, pos, eOpts) {
        var refs = this.getReferences(),
            model = this.getViewModel(),
            currentYear = new Date().getFullYear(), //yr in 4 digits
            currentFy = Number(currentYear.toString().substr(-2)), //yr in 2 digits
            createNextFyEndDate = new Date(new Date().getFullYear() + "-10-01T00:00:00-04:00"),
            rec = null;

        //if today is 10/1 or later, FY is in next FY
        if (new Date() >= createNextFyEndDate) {
            currentFy++;
        }

        //MB-473
        refs.comboFy.setValue(currentFy);

        //save this value to the viewmodel variable binded to the checkbox
        var storedMissingStmtDt = localStorage.getItem("purchaseViewChkboxMissingStmtDtValue");
        if (storedMissingStmtDt) {
            model.set("missingStmtDtChecked", storedMissingStmtDt);
        }

        //when actions within the view or its subview finishes, it should return to
        model.set("returnToView", this.view.routeId);

        //chekc if id is passed in
        if (component.requestId && component.requestId !== 0) {
            //the request record should be prepared by the before action already
            rec = model.get("currentRequest");

            if (rec) {
                model.set("generalInfo", rec);
                model.set("record", rec);

                //MB-186
                model.set("isPurchase", false);
                //BHs can edit actuals and update item status, note, received date
                //if the request status is processed or completed
                if (bcp.util.CommonUtil.isUserInRole(["Bankcard Holder"])) {
                    model.set("isPurchase", true);
                }

                refs.detail.destroy();
                bcp.util.CommonFunctions.setupReadOnlyRequestDetailView(rec, this, this.getView(), false);
                this.showView("detail");
            }
        } else {
            this.showView("list");
        }
    }
});
